#!/usr/bin/env node
// Fetches a Linear issue and prints the resolve-issue-context JSON contract
// to stdout. Invoked by the resolve-issue-context agent — the plugin bundles
// no Linear MCP server, so this helper is that agent's only Linear read path.
//
// Usage:  LINEAR_API_KEY=lin_api_xxx node fetch-issue.mjs ENG-123
//
// Always exits 0 and always prints a single JSON object: on any failure it
// prints the degraded shape with a non-null `resolveError`, so the caller can
// surface the error and STOP rather than proceed against missing data.

import { createLinearClient } from "./linearClient.mjs";

const degraded = (id, error) => ({
  source: id ? `Linear ${id}` : "Linear",
  issueId: id ?? null,
  title: null,
  status: "unresolved",
  labels: [],
  url: null,
  assignee: null,
  description: null,
  comments: [],
  resolveError: error,
});

async function main() {
  const id = process.argv[2];
  const apiKey = process.env.LINEAR_API_KEY;

  if (!id) return degraded(null, "unresolved — no Linear issue ID provided");
  if (!apiKey) return degraded(id, "unresolved — LINEAR_API_KEY unset");

  try {
    const issue = await createLinearClient(apiKey).fetchIssue(id);
    if (!issue) return degraded(id, `unresolved — Linear issue ${id} not found`);

    return {
      source: `Linear ${issue.identifier}`,
      issueId: issue.identifier,
      title: issue.title,
      status: issue.state?.name ?? null,
      labels: (issue.labels?.nodes ?? []).map((label) => label.name),
      url: issue.url ?? null,
      assignee: null,
      description: issue.description ?? "",
      comments: (issue.comments?.nodes ?? []).map((comment) => ({
        author: comment.user?.displayName ?? "unknown",
        date: (comment.createdAt ?? "").slice(0, 10),
        body: comment.body ?? "",
      })),
      resolveError: null,
    };
  } catch (error) {
    const detail = error.cause ? ` (${Object.values(error.cause).join(" ")})` : "";
    return degraded(id, `unresolved — ${error.message}${detail}`);
  }
}

process.stdout.write(JSON.stringify(await main()));
// Zero-dependency Linear GraphQL client for the autopilot plugin.
//
// Ported from .github/actions/release-action/src/tickets/linearClient.ts, with the
// IssueByIdentifier query extended to also return state, labels, assignee, and
// comments so the output matches the resolve-issue-context JSON contract. Uses the
// global `fetch` (Node 18+), so there is no install step and no dependency tree.
//
// The plugin bundles no Linear MCP server, so this client is the agents' only
// Linear read path (interactive and headless/CI alike), keyed by LINEAR_API_KEY.

const linearApiUrl = "https://api.linear.app/graphql";

const issueQuery = `
  query IssueByIdentifier($id: String!) {
    issue(id: $id) {
      identifier
      title
      url
      description
      state { name }
      labels { nodes { name } }
      comments(orderBy: createdAt) { nodes { user { displayName } createdAt body } }
    }
  }
`;

const teamMembersQuery = `
  query TeamMembers($team: String!) {
    viewer { id name displayName }
    teams(filter: { key: { eq: $team } }) {
      nodes { members { nodes { id name displayName active } } }
    }
  }
`;

/**
 * Create a Linear API client.
 *
 * @param {string} apiKey - Linear API key (starts with `lin_api_`).
 * @returns {{ fetchIssue: (id: string) => Promise<object|null>, fetchTeamMembers: (team: string) => Promise<object|null> }}
 */
export function createLinearClient(apiKey) {
  const query = async (queryText, variables) => {
    const response = await fetch(linearApiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: apiKey,
      },
      body: JSON.stringify({ query: queryText, variables }),
    });

    if (!response.ok) {
      throw new Error("Linear API request failed", {
        cause: { status: response.status, statusText: response.statusText },
      });
    }

    const result = await response.json();
    const firstError = result.errors?.[0];
    if (firstError) {
      const { message } = firstError;
      if (message.includes("not found") || message.includes("Entity not found")) {
        return null;
      }
      throw new Error("Linear API returned a GraphQL error", { cause: { message } });
    }

    return result.data ?? null;
  };

  return {
    async fetchIssue(id) {
      const data = await query(issueQuery, { id });
      return data?.issue ?? null;
    },
    async fetchTeamMembers(team) {
      const data = await query(teamMembersQuery, { team });
      // An unknown team key yields an empty nodes array, not a GraphQL error.
      const teamNode = data?.teams?.nodes?.[0];
      if (!teamNode) return null;
      return { viewer: data?.viewer ?? null, members: teamNode.members?.nodes ?? [] };
    },
  };
}

