  const reads = buildGhReadCommands({ owner: "octo", repo: "demo", pr: 42 });
  const writeFlags = ["-X", "--method", "--input"];
  expect(Object.keys(reads).sort()).toEqual(["comments", "meta", "reviews", "threads"]);
